/// <summary>
/// Extension of the class <c>TAMRebatePost</c>
/// </summary>
[ExtensionOf(classStr(TAMRebatePost))]
final class METTAMRebatePost_Extension
{
}

Method.Source:
/// <summary>
/// CB705 Batch posting will be skipped if skip posting check box is enabled in rebate line. Context class instance will contain information whether it's called from batch or form
/// </summary>
/// <returns>boolean</returns>
protected boolean validatePost()
{
    if (TAMRebateTable::find(this.rebateId()).METSkipPosting && this.rebateTransactionType == TAMRebateTransactionType::Rebate )
    {
        METSkipPostingContext_BEC context = METSkipPostingContext_BEC::current();
        if (context.isCalledFromRebateBatch)
        {
            throw error(strFmt("@MET:ManualRebatePosting", this.rebateId()));
        }
    }
    return next validatePost();
}

/// <summary>
/// Created for the FSD - CB201, Rebates Extension - Undertake Build -  External Data Sources
/// Update the provision & rebate posted on the external sell data based on the transaction line being posted.
/// </summary>
/// <param name = "_postDateTransaction"></param>
protected void processRebateDateTransactions(TAMRebatePostDateTransaction _postDateTransaction)
{
    // Run the MET tier rate calculation service job if the rebate deal is marked as a MET volumetric tier deal
    // 281410 - CB201- For Volumetric rebate Calculate tier rate rebate is not working properly if we click on Process provision without doing the Calculate tier rate rebate
    if (this.rebateDeal().METVolumetricTierDeal)
    {
        METTierRateTrans mETTierRateTrans;

        // Delete existing tier rate transactions for the same date range and rebate deal to avoid duplicates
        delete_from mETTierRateTrans
            where mETTierRateTrans.TAMRebateDealId == this.rebateDeal().deal
            && mETTierRateTrans.FromDate == fromDate
            && mETTierRateTrans.ToDate == toDate;

        METTierRateCalculationContract contract = new METTierRateCalculationContract();
        METTierRateCalculationService  service  = new METTierRateCalculationService();

        // Set required contract parameters
        contract.parmFromDate(fromDate);
        contract.parmToDate(toDate);
        contract.parmRebateDealRecId(this.rebateDeal().deal);

        // Run the service
        service.process(contract);
    }
    // 281410 - CB201- For Volumetric rebate Calculate tier rate rebate is not working properly if we click on Process provision without doing the Calculate tier rate rebate


    next processRebateDateTransactions(_postDateTransaction);

    TAMRebateDeal       deal = this.rebateDeal();
    TAMRebateDateTrans  dateTrans;

    select firstonly RecId, METExternalSellTransactionNumber from dateTrans
        where dateTrans.RebateDeal == deal.RecId
        && dateTrans.RebatePosted == NoYes::Yes;

    if (dateTrans.RecId && rebateTransactionType == TAMRebateTransactionType::Provision)
    {
        METRebateScanSupplierTable externalSellData;

        ttsbegin;
        select forupdate externalSellData
            where externalSellData.TransactionNumber == dateTrans.METExternalSellTransactionNumber
            && externalSellData.ProvisionPosted == NoYes::No;

        if (externalSellData.RecId)
        {
            externalSellData.ProvisionPosted = NoYes::Yes;
            externalSellData.update();
        }
        ttscommit;
    }
    else if (dateTrans.RecId && rebateTransactionType == TAMRebateTransactionType::Rebate)
    {
        METRebateScanSupplierTable externalSellData;

        ttsbegin;
        select forupdate externalSellData
            where externalSellData.TransactionNumber == dateTrans.METExternalSellTransactionNumber
            && externalSellData.RebatePosted == NoYes::No;

        if (externalSellData.RecId)
        {
            externalSellData.RebatePosted = NoYes::Yes;
            externalSellData.update();
        }
        ttscommit;
    }
}
